+    ].join('\n');
+    final String reply;
+    if (prompt.contains('context-hygiene judge')) {
+      reply = '[]';
+    } else if (prompt.contains('Write a checkpoint')) {
+      reply = _checkpointReply;
+    } else {
+      reply = turnAnswers[_answered++ % turnAnswers.length];
+    }
