+    test('env set → the trigger-applied settings', () {
+      final settings = resolveBenchCompactionSettings(
+        CompactionSettings.forWindow(200000),
+        window: 200000,
+        env: {'FAH_COMPACT_TRIGGER_TOKENS': '64000'},
