  // bench-run knob (`FAH_COMPACT_TRIGGER_TOKENS`) and must win over
  // both the defaults and a host default override. Unset env =
  // byte-identical base.
  return resolveBenchCompactionSettings(
    base,
    window: _effectiveContextWindow,
    env: environment,
  );
}

