+        provider: 'test-provider',
+        model: 'test-model',
+        usage: Usage.zero,
+        stopReason: StopReason.toolUse,
+        timestamp: DateTime.utc(2026),
+      ),
+    );
+    await seed.appendMessage(
+      ToolResultMessage(
+        toolCallId: 'call-seed-1',
+        toolName: 'read',
+        content: [const TextContent(text: _toolResultMarker)],
