+  }
+
+  AgentCli cli(
+    MemoryExecutionEnv env,
+    _CompactionAwareStream stream, {
+    Map<String, String> environment = const {
+      'FAH_COMPACT_TRIGGER_TOKENS': '$_benchTriggerTokens',
+    },
+  }) => AgentCli(
