String _briefPath(String path, {String? cwd, String? home}) {
  var p = path;
  final c = cwd ?? '';
  if (c.isNotEmpty && (p == c || p.startsWith('$c/'))) {
    p = p == c ? '.' : p.substring(c.length + 1);
  }
  final h = home ?? '';
  if (h.isNotEmpty && (p == h || p.startsWith('$h/'))) {
    p = '~${p.substring(h.length)}';
  }
  return p;
}

