const _hiddenMarkerTokens = hiddenRecordMarkerTokens;

/// Token budget for the windowed resume walk (gh-968, AC-R3): the
/// transcript tally the walk may stop at, derived from the SAME basis as
/// the ctx meter, `_maybeAutoCompact` and the loop's over-window guard.
///
/// `effectiveContextWindow − system-prompt/tool-schema overhead −
/// reserveTokens`, floored at 0. The old budget priced the transcript
/// alone against the window, so a resume filled the resident records to
/// ~the whole window and the meter — which adds the unanchored
/// system+tools overhead on top — read past 100% (the reported
/// `127%/200k` resume). With the parity budget, meter = transcript +
/// overhead ≤ window − reserve: below the compaction trigger, below the
/// guard, on every fresh resume.
int resumeParityBudget({
  required int effectiveContextWindow,
  required int reserveTokens,
  String? systemPrompt,
  List<Tool> tools = const [],
}) {
  final budget =
      effectiveContextWindow -
      estimateRequestOverheadTokens(systemPrompt, tools) -
      reserveTokens;
  return budget > 0 ? budget : 0;
}

/// The index of the OLDEST record of [branch] (root-first) to keep so the
/// projected estimate of the kept suffix stays within [budget] — walking
/// from the newest end backward, the record that would push the tally
/// PAST the budget is dropped together with everything older — or `null`
===
  /// transcript estimate plus the system-prompt / tool-schema overhead
  /// whenever no provider-usage anchor prices them in.
  int _requestTokens() => estimateRequestTokens(
    state.messages,
    systemPrompt: state.systemPrompt,
    tools: state.tools,
  );

  /// Runs both passes; returns whether the context ended under pressure.
  Future<bool> run({bool force = false}) async {
    if (window <= 0) return true;
    final trigger = window - settings.reserveTokens;
    if (!force && _requestTokens() <= trigger) {
      return true;
    }
    // Tier 2 LRU re-hide (issue #1379): evict least-recently-used
    // expansion artifacts first — the oldest expand call/result pairs
    // re-fold into markers before the judge ever sees the ledger.
    await _runLruRehidePasses(trigger);
    if (!await _runHidePasses(trigger)) return false;
    if (!await _runCheckpointPasses(trigger)) return false;
    return _requestTokens() <= trigger;
  }

  /// Tier 2 LRU re-hide (issue #1379): after an expand storm, the oldest
  /// expand call/result pairs re-fold into markers at the next pressure
  /// event — the newest expansion is always kept. LRU order is derived
  /// from file order alone (an expansion's recency IS its record position;
  /// nothing extra is stored), so replay is deterministic. The re-hidden
  /// segments themselves never left hidden-but-expandable state — their
  /// markers stay in the session — so the lossless invariant (#148 AC2)

